solutionCode:
pub fn recibo(nome: String, pecas: i32, preco: i32) -> String {
    let total = pecas * preco;
    format!("{} levou {} pecas por {}", nome, pecas, total)
}

testsCode:
use desafio::recibo;

#[test]
fn testa_o_recibo_da_ana() {
    assert_eq!(recibo(String::from("Ana"), 3, 5), "Ana levou 3 pecas por 15");
}

#[test]
fn testa_o_recibo_da_bia() {
    assert_eq!(recibo(String::from("Bia"), 2, 7), "Bia levou 2 pecas por 14");
}
